test('vatSummary with complex invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2, discountPercent: 20 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  const issued = issueInvoice(inv.value, []).value;

  const result = vatSummary([issued]);
  assert.equal(result.length, 3);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);

  // Calculate expected values
  let expected21Base = 0,
    expected21VAT = 0;
  let expected9Base = 0,
    expected9VAT = 0;
  let expected0Base = 0,
    expected0VAT = 0;

  for (const line of issued.lines) {
    const base = lineTotal(line) - lineDiscount(line);
    const vat = lineVAT(line);
    if (line.vatRate === 21) {
      expected21Base += base;
      expected21VAT += vat;
    } else if (line.vatRate === 9) {
      expected9Base += base;
      expected9VAT += vat;
    } else {
      expected0Base += base;
      expected0VAT += vat;
    }
  }

  assert.equal(result[0].base, expected21Base);
  assert.equal(result[0].vat, expected21VAT);
  assert.equal(result[1].base, expected9Base);
  assert.equal(result[1].vat, expected9VAT);
  assert.equal(result[2].base, expected0Base);
  assert.equal(result[2].vat, expected0VAT);
});

