import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVAT, roundCents } from './invoices.js';

/**
 * Get overdue invoices as of a given date.
 * @param {Array} invoices - all invoices
 * @param {string} asOf - report date in YYYY-MM-DD format
 * @returns {Array} invoices with status 'issued' or 'partially_paid' and dueDate < asOf,
 *                  sorted by daysOverdue descending (most overdue first)
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => ['issued', 'partially_paid'].includes(inv.status))
    .filter((inv) => daysBetween(inv.dueDate, asOf) > 0)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Summarize VAT across invoices by rate.
 * @param {Array} invoices - all invoices
 * @returns {Array} VAT summary [{ rate, base, vat }] sorted by rate descending
 */
export function vatSummary(invoices) {
  const summary = {};

  // Accumulate base and VAT by rate for issued, partially_paid, and paid invoices
  invoices
    .filter((inv) => ['issued', 'partially_paid', 'paid'].includes(inv.status))
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        if (!summary[rate]) {
          summary[rate] = { base: 0, vat: 0 };
        }
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVAT(line);
        summary[rate].base += base;
        summary[rate].vat += vat;
      });
    });

  // Convert to array and sort by rate descending
  return Object.entries(summary)
    .map(([rate, { base, vat }]) => ({
      rate: parseInt(rate, 10),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * 0.04% per day of the amount still due for overdue invoices, 0 if not overdue.
 * @param {{ dueDate: string, status: string, payments: Array }} invoice
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {number} late fee in cents
 */
export function lateFee(invoice, asOf) {
